import { requireArea } from "@/lib/rbac";
import { listApps, listBoards, getBoard } from "@/lib/actions-board";
import { BoardClient } from "@/components/admin/BoardClient";

export const dynamic = "force-dynamic";

export default async function AdminBoardPage({ searchParams }: { searchParams: Promise<{ b?: string; app?: string }> }) {
  await requireArea("platform");
  const sp = await searchParams;

  const [apps, allBoards] = await Promise.all([listApps(), listBoards()]);

  // Active app filter: an app id, the literal "unassigned", or undefined (all).
  const appParam = sp.app;
  const activeApp =
    appParam === "unassigned" ? "unassigned" : apps.find((a) => a.id === appParam)?.id ?? null;

  // Boards visible under the current app filter.
  const visibleBoards =
    activeApp === "unassigned"
      ? allBoards.filter((b) => b.appId === null)
      : activeApp
        ? allBoards.filter((b) => b.appId === activeApp)
        : allBoards;

  // Pick the active board: honour ?b= when it's in the visible set, else the
  // first visible board.
  const activeId = visibleBoards.find((b) => b.id === sp.b)?.id ?? visibleBoards[0]?.id ?? "";
  const board = activeId ? await getBoard(activeId) : null;

  return (
    <BoardClient
      apps={apps}
      boards={visibleBoards}
      board={board}
      activeApp={activeApp}
      unassignedCount={allBoards.filter((b) => b.appId === null).length}
    />
  );
}
